from datetime import UTC, datetime, timedelta, tzinfo

class FakeZone(tzinfo):
    """UTC+1, switching to UTC+2 from 1 April at 02:00 local (no fall-back)."""
    def utcoffset(self, dt):
        return timedelta(hours=1) + self.dst(dt)
    def dst(self, dt):
        switch = datetime(dt.year, 4, 1, 2)
        return timedelta(hours=1) if dt.replace(tzinfo=None) >= switch else timedelta(0)
    def tzname(self, dt):
        return "FST" if self.dst(dt) else "FT"
    def fromutc(self, dt):
        local = dt + timedelta(hours=1)          # try standard time first
        if local.replace(tzinfo=None) >= datetime(dt.year, 4, 1, 2):
            local += timedelta(hours=1)
        return local

z = FakeZone()
print(datetime(2025, 3, 1, 12, tzinfo=z).isoformat())   # 2025-03-01T12:00:00+01:00
print(datetime(2025, 5, 1, 12, tzinfo=z).tzname())      # FST
utc = datetime(2025, 4, 1, 1, 30, tzinfo=UTC)
print(utc.astimezone(z).isoformat())                    # 2025-04-01T03:30:00+02:00
